// A tiny pastel boutique, built entirely from friendly low-poly shapes.
const mat=(color,rough=.8)=>new THREE.MeshStandardMaterial({color,roughness:rough});
function box(parent,x,y,z,w,h,d,m,rot=0){let o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.rotation.y=rot;o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function sphere(parent,x,y,z,r,m,sx=1,sy=1,sz=1){let o=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;parent.add(o);return o}
function cylinder(parent,x,y,z,r1,r2,h,m){let o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,14),m);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o}
function textSign(parent,text,x,y,z,color='#fff9fd'){let c=document.createElement('canvas');c.width=512;c.height=128;let g=c.getContext('2d');g.fillStyle='#bd62a1';g.beginPath();g.roundRect(5,5,502,118,28);g.fill();g.fillStyle=color;g.textAlign='center';g.textBaseline='middle';g.font='bold 54px system-ui';g.fillText(text,256,66);let tex=new THREE.CanvasTexture(c),sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true}));sp.position.set(x,y,z);sp.scale.set(3.2,.8,1);parent.add(sp)}
function mannequin(parent,x,z,outfit,hair,skirt=false){let g=new THREE.Group();g.position.set(x,0,z);parent.add(g);let skin=mat('#f3c5a5'),hairM=mat(hair),cloth=mat(outfit),shoe=mat('#f8eef9');sphere(g,0,1.56,0,.24,skin,.85,1.12,.8);sphere(g,-.04,1.68,-.08,.245,hairM,.92,.72,.92);sphere(g,-.22,1.57,.01,.115,hairM,.9,1.4,.8);sphere(g,.20,1.57,.01,.115,hairM,.9,1.35,.8);sphere(g,-.082,1.55,.208,.022,mat('#36263a'));sphere(g,.082,1.55,.208,.022,mat('#36263a'));box(g,0,1.08,0,.44,.58,.25,cloth,skirt?0:.03);cylinder(g,-.12,.59,0,.08,.09,.43,skin);cylinder(g,.12,.59,0,.08,.09,.43,skin);sphere(g,-.12,.34,.03,.12,shoe,1.1,.5,1.5);sphere(g,.12,.34,.03,.12,shoe,1.1,.5,1.5);cylinder(g,-.29,1.08,0,.065,.07,.43,skin);cylinder(g,.29,1.08,0,.065,.07,.43,skin);g.userData.bob=Math.random()*6;customers.push(g);return g}
function makeRack(parent,x,z){let gold=mat('#e7af69'),rod=box(parent,x,1.7,z,.055,.06,.94,gold);cylinder(parent,x-.38,.88,z,.04,.05,1.75,gold);cylinder(parent,x+.38,.88,z,.04,.05,1.75,gold);box(parent,x,.09,z,.92,.12,.3,gold);let colors=['#ff8cb8','#b9a2ff','#f2c56b','#83c9bb','#f58e80'];for(let i=0;i<5;i++){let xx=x-.31+i*.155;box(parent,xx,1.31,z,.14,.53,.2,mat(colors[i]),(i-2)*.07);box(parent,xx,1.59,z,.055,.12,.13,gold)}}
function buildWorld(){scene=new THREE.Scene();scene.background=new THREE.Color('#d7b8e4');scene.fog=new THREE.Fog('#d7b8e4',13,26);camera=new THREE.PerspectiveCamera(36,1,.1,100);camera.position.set(6.7,6.4,9.3);camera.lookAt(0,1,0);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;worldEl.prepend(renderer.domElement);scene.add(new THREE.HemisphereLight('#fff5ff','#b095b6',2));let key=new THREE.DirectionalLight('#fff3dc',3.3);key.position.set(-4,8,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);let pinkLight=new THREE.PointLight('#ff8cbe',14,8);pinkLight.position.set(0,3,-2.5);scene.add(pinkLight);
studio=new THREE.Group();scene.add(studio);let floor=mat('#f4d8e6'),wall=mat('#f9e9f1'),wall2=mat('#e8d8f6'),dark=mat('#5a3b62'),wood=mat('#bd8d79'),white=mat('#fff8fa'),pink=mat('#ff8ebc'),gold=mat('#edbb70');box(studio,0,-.16,0,9,.3,7,floor);box(studio,0,2.1,-3.45,9,4.4,.24,wall);box(studio,-4.45,2.1,0,.18,4.4,7,wall2);box(studio,4.45,2.1,0,.18,4.4,7,wall);box(studio,0,4.35,-1.7,9,.14,3.55,white);box(studio,0,.02,-3.28,8.85,.16,.12,dark);
// pastel wall panels and boutique sign
for(let i=0;i<5;i++)box(studio,-3.5+i*1.65,2.1,-3.28,1.5,3.75,.035,i%2?wall:mat('#f5e1f3'));
textSign(studio,'VELVET & VOGUE',0,3.3,-3.05);box(studio,0,2.83,-3.06,2.2,.07,.07,gold);
// tiled pastel floor
for(let i=0;i<8;i++)for(let j=0;j<6;j++){if((i+j)%2===0)box(studio,-3.94+i*1.13,.002,-2.9+j*1.12,1.08,.018,1.07,mat('#f8e7f0'))}
// large arched window on left
box(studio,-4.32,2.25,-.6,.035,2.55,2.4,mat('#b8d5ea'));box(studio,-4.29,2.25,-.6,.06,.1,2.55,white);box(studio,-4.28,2.25,-.6,.07,2.65,.12,white);box(studio,-4.25,2.25,-.6,.08,2.4,.08,white);
// checkout desk and tablet register
box(studio,.1,.56,1.52,2.05,1.08,.75,wood);box(studio,.1,1.13,1.52,2.12,.12,.81,pink);box(studio,.1,.72,1.12,.6,.35,.04,mat('#d7b098'));box(studio,.5,1.3,1.35,.36,.33,.06,dark,-.12);box(studio,.5,1.3,1.31,.3,.26,.025,mat('#b9a2ff'),-.12);textSign(studio,'CHECKOUT',.1,1.66,1.5);
// boutique racks
makeRack(studio,-2.75,.1);makeRack(studio,2.55,-.55);
// display plinths, bags, plants
for(let [x,z,col] of [[-1.6,-1.65,'#d7c2ef'],[1.65,-1.55,'#ffd3e4']]){box(studio,x,.35,z,.88,.68,.8,mat(col));box(studio,x,.72,z,.92,.09,.84,white);sphere(studio,x,.98,z,.24,pink,1.25,.25,.7);}
// leafy plant pots
for(let [x,z] of [[-3.8,2.25],[3.75,-2.5]]){cylinder(studio,x,.3,z,.3,.23,.55,mat('#e995b4'));for(let i=0;i<6;i++){let a=i*Math.PI/3;sphere(studio,x+Math.cos(a)*.25,.82+(i%2)*.18,z+Math.sin(a)*.25,.18,mat(i%2?'#68b99b':'#7ecbad'),.65,1.6,.7)}}
// runway rug and hanging lamps
box(studio,0,.015,-.1,1.35,.035,2.8,mat('#edcae7'));for(let x of [-2,0,2]){cylinder(studio,x,3.75,-1.4,.035,.035,.8,gold);sphere(studio,x,3.28,-1.4,.29,mat('#fff0ad'),1,.4,1)}
// stylists and visitors
mannequin(studio,-1.6,.8,'#cc9cec','#5b3b58',true);mannequin(studio,1.65,.55,'#7fcabd','#402c47');mannequin(studio,-3.25,-1.1,'#ffb2cb','#714263',true);
clock=new THREE.Clock();resize();window.addEventListener('resize',resize);animate();}
function resize(){if(!renderer)return;let r=worldEl.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}
let dragging=false,lastX=0,rotY=0,rotX=0;worldEl.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;worldEl.setPointerCapture(e.pointerId)});worldEl.addEventListener('pointermove',e=>{if(!dragging)return;let dx=e.clientX-lastX;lastX=e.clientX;rotY+=dx*.005;studio.rotation.y=rotY});worldEl.addEventListener('pointerup',()=>dragging=false);worldEl.addEventListener('pointercancel',()=>dragging=false);
function addCustomer(){if(customers.length>12||!studio)return;let shades=['#ff9fc4','#c4a0f4','#ffcb71','#82cbb7','#f28983'];let c=mannequin(studio,(Math.random()-.5)*5.5,2.1+Math.random()*1.5,shades[Math.floor(Math.random()*shades.length)],['#59324f','#46354d','#704254'][Math.floor(Math.random()*3)],Math.random()>.5);c.userData.phase=Math.random()*8}
function upgradeScene(id){if(!studio)return;let u=upgrades.find(a=>a.id===id);if(!u)return;let levels=levelOf(id);if(id==='rack'&&levels<=3)makeRack(studio,-3.55+levels*.55,-1.2);if(id==='lights'){let l=new THREE.PointLight('#ff64b4',12,7);l.position.set((levels%2?3:-3),2.7,-2.8);studio.add(l)}if(id==='runway'){box(studio,0,.05,.2,2,.07,3,mat('#d7a4ec'));for(let x of [-1.25,1.25])for(let z of [-1,-.3,.4,1.1])sphere(studio,x,.24,z,.095,mat('#ffd879'))}if(id==='cafe'){cylinder(studio,3.35,.5,1.55,.52,.52,.95,mat('#bd8d79'));for(let z of [1.05,2.05]){cylinder(studio,3.35,.68,z,.14,.14,.38,mat('#ff9bbd'));cylinder(studio,3.35,.9,z,.15,.15,.09,mat('#fff1f6'))}}if(id==='loft'||id==='campaign'||id==='empire'){let col=id==='loft'?'#9c7bc8':id==='campaign'?'#ed82a9':'#efc477';box(studio,0,4.45,-1.7,8.9,.12,.08,mat(col))}}
function animate(){requestAnimationFrame(animate);if(!renderer)return;let t=clock.getElapsedTime();for(let c of customers){c.position.y=Math.sin(t*2+c.userData.bob)*.018;c.rotation.y=Math.sin(t*.7+c.userData.phase)*.08}renderer.render(scene,camera)}
setInterval(()=>{let inc=income()/30;game.cash+=inc;game.total+=inc;game.fans+=Math.max(.15,inc/12);if(Math.floor(game.total/120)+1>game.day)game.day=Math.floor(game.total/120)+1;renderUI()},2000);
renderUI();if(game.started)$('#welcome').classList.add('hidden');buildWorld();for(let i=0;i<5;i++)addCustomer();for(let u of upgrades)for(let i=0;i<Math.min(levelOf(u.id),2);i++)upgradeScene(u.id);
</script></body></html>

