$('#report').textContent=totalUp()===0?'Your first fashion fans are on their way. Give the cash register a tap to kick things off!':`Your studio earns ${money(income())} every minute. ${Math.floor(game.fans)} fashion fans have discovered your fabulous looks!`;$('#sound').textContent=game.sound?'🔊':'🔇';save();updateUpgradeVisuals()}
function updateUpgradeVisuals(){if(studio){studio.traverse(o=>{if(o.isPointLight&&o!==scene.children[1])o.intensity=10+Math.sin(performance.now()*.003)*2})}}
