function collect(){let amount=income()*2;game.cash+=amount;game.total+=amount;game.fans+=Math.max(1,Math.floor(amount/8));game.xp+=Math.max(5,Math.floor(amount/4));showToast('✨ Sales collected: +'+money(amount));sound(740);addCustomer();if(game.total>=100&&game.total-amount<100){game.cash+=50;showToast('🌟 Challenge complete! +$50 bonus!')}renderUI()}
function startGame(){game.started=true;$('#welcome').classList.add('hidden');sound(760);save()}$('#start').onclick=startGame;$('#collect').onclick=collect;$('#sound').onclick=()=>{game.sound=!game.sound;renderUI();sound()};$('#reset').onclick=()=>{if(confirm('Start a new studio from scratch?')){localStorage.removeItem('velvetTycoon');location.reload()}};

