function buildWorld(){scene=new THREE.Scene();scene.background=new THREE.Color('#d7b8e4');scene.fog=new THREE.Fog('#d7b8e4',13,26);camera=new THREE.PerspectiveCamera(36,1,.1,100);camera.position.set(6.7,6.4,9.3);camera.lookAt(0,1,0);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;worldEl.prepend(renderer.domElement);scene.add(new THREE.HemisphereLight('#fff5ff','#b095b6',2));let key=new THREE.DirectionalLight('#fff3dc',3.3);key.position.set(-4,8,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);let pinkLight=new THREE.PointLight('#ff8cbe',14,8);pinkLight.position.set(0,3,-2.5);scene.add(pinkLight);studio=new THREE.Group();scene.add(studio);let floor=mat('#f4d8e6'),wall=mat('#f9e9f1'),wall2=mat('#e8d8f6'),dark=mat('#5a3b62'),wood=mat('#bd8d79'),white=mat('#fff8fa'),pink=mat('#ff8ebc'),gold=mat('#edbb70');box(studio,0,-.16,0,9,.3,7,floor);box(studio,0,2.1,-3.45,9,4.4,.24,wall);box(studio,-4.45,2.1,0,.18,4.4,7,wall2);box(studio,4.45,2.1,0,.18,4.4,7,wall);box(studio,0,4.35,-1.7,9,.14,3.55,white);box(studio,0,.02,-3.28,8.85,.16,.12,dark);for(let i=0;i<5;i++)box(studio,-3.5+i*1.65,2.1,-3.28,1.5,3.75,.035,i%2?wall:mat('#f5e1f3'));textSign(studio,'VELVET & VOGUE',0,3.3,-3.05);box(studio,0,2.83,-3.06,2.2,.07,.07,gold);
for(let i=0;i<8;i++)for(let j=0;j<6;j++)if((i+j)%2===0)box(studio,-3.94+i*1.13,.002,-2.9+j*1.12,1.08,.018,1.07,mat('#f8e7f0'));box(studio,-4.32,2.25,-.6,.035,2.55,2.4,mat('#b8d5ea'));box(studio,-4.29,2.25,-.6,.06,.1,2.55,white);box(studio,-4.28,2.25,-.6,.07,2.65,.12,white);box(studio,-4.25,2.25,-.6,.08,2.4,.08,white);
box(studio,.1,.56,1.52,2.05,1.08,.75,wood);box(studio,.1,1.13,1.52,2.12,.12,.81,pink);box(studio,.1,.72,1.12,.6,.35,.04,mat('#d7b098'));box(studio,.5,1.3,1.35,.36,.33,.06,dark,-.12);box(studio,.5,1.3,1.31,.3,.26,.025,mat('#b9a2ff'),-.12);textSign(studio,'CHECKOUT',.1,1.66,1.5);makeRack(studio,-2.75,.1);makeRack(studio,2.55,-.55);
for(let [x,z,col] of [[-1.6,-1.65,'#d7c2ef'],[1.65,-1.55,'#ffd3e4']]){box(studio,x,.35,z,.88,.68,.8,mat(col));box(studio,x,.72,z,.92,.09,.84,white);sphere(studio,x,.98,z,.24,pink,1.25,.25,.7)}for(let [x,z] of [[-3.8,2.25],[3.75,-2.5]]){cylinder(studio,x,.3,z,.3,.23,.55,mat('#e995b4'));for(let i=0;i<6;i++){let a=i*Math.PI/3;sphere(studio,x+Math.cos(a)*.25,.82+(i%2)*.18,z+Math.sin(a)*.25,.18,mat(i%2?'#68b99b':'#7ecbad'),.65,1.6,.7)}}box(studio,0,.015,-.1,1.35,.035,2.8,mat('#edcae7'));for(let x of [-2,0,2]){cylinder(studio,x,3.75,-1.4,.035,.035,.8,gold);sphere(studio,x,3.28,-1.4,.29,mat('#fff0ad'),1,.4,1)}mannequin(studio,-1.6,.8,'#cc9cec','#5b3b58',true);mannequin(studio,1.65,.55,'#7fcabd','#402c47');mannequin(studio,-3.25,-1.1,'#ffb2cb','#714263',true);clock=new THREE.Clock();resize();window.addEventListener('resize',resize);animate()}
function resize(){if(!renderer)return;let r=worldEl.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}let dragging=false,lastX=0,rotY=0;worldEl.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;worldEl.setPointerCapture(e.pointerId)});worldEl.addEventListener('pointermove',e=>{if(!dragging)return;let dx=e.clientX-lastX;lastX=e.clientX;rotY+=dx*.005;studio.rotation.y=rotY});worldEl.addEventListener('pointerup',()=>dragging=false);worldEl.addEventListener('pointercancel',()=>dragging=false);
